/**
 * Runs FPA-STILL on the bundled case photos with the same on-device
 * landmarker as live assessment, and seals one PhotoRecord per photo.
 */
import { analyzeStill } from '../core';
import { uid } from '../data/db';
import { seal } from '../data/integrity';
import { APP_INFO } from '../data/records';
import type { PhotoRecord } from '../data/types';
import type { PatientCase } from './library';

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`image load failed: ${src}`));
    img.src = src;
  });
}

export async function analyzeCase(c: PatientCase, onProgress?: (done: number, total: number, msg: string) => void): Promise<PhotoRecord[]> {
  const total = c.photos.length;
  const { getEngine } = await import('../vision/landmarker');
  const engine = await getEngine((m) => onProgress?.(0, total, m));
  const out: PhotoRecord[] = [];
  for (const [i, p] of c.photos.entries()) {
    onProgress?.(i, total, `${p.label} 분석 중…`);
    const url = new URL(p.file, document.baseURI).href;
    const img = await loadImage(url);
    const obs = await engine.detectImage(img);
    const analysis = analyzeStill(obs, { affectedSide: c.affectedSide, expression: p.expression, exclude: p.exclude });
    out.push(
      await seal<PhotoRecord>({
        schema: 1,
        id: uid(),
        createdAt: new Date().toISOString(),
        source: 'case',
        caseId: c.id,
        photoId: p.id,
        imageUrl: p.file,
        takenAt: p.takenAt,
        day: p.day,
        expression: p.expression,
        label: p.label,
        note: p.note ?? null,
        affectedSide: c.affectedSide,
        app: APP_INFO,
        engine: engine.info,
        analysis,
      }),
    );
  }
  onProgress?.(total, total, '완료');
  return out;
}
